<script>document.querySelectorAll('.news-carousel').forEach(carousel=>{const track=carousel.querySelector('.news-carousel-track'),slides=[...track.children],thumbs=[...document.querySelectorAll('[data-news-slide]')],prev=carousel.querySelector('.prev'),next=carousel.querySelector('.next');let active=0,timer;const show=(index,animate=true)=>{active=(index+slides.length)%slides.length;track.style.transition=animate?'transform .65s cubic-bezier(.2,.8,.2,1)':'none';track.style.transform=`translate3d(-${active*100}%,0,0)`;thumbs.forEach((thumb,i)=>thumb.classList.toggle('is-active',i===active))};const play=()=>{if(slides.length<2)return;clearInterval(timer);timer=setInterval(()=>show(active+1),5000)};const restart=()=>{show(active+1);play()};prev?.addEventListener('click',()=>{show(active-1);play()});next?.addEventListener('click',restart);thumbs.forEach((thumb,i)=>thumb.addEventListener('click',()=>{show(i);play()}));new ResizeObserver(()=>show(active,false)).observe(carousel);show(0,false);play()});</script>
